use vexel_geometry::{Edge, Point};
use vexel_scene::{
    DashJoin, DashSegment, JobDashCache, JobDashRange, JobRasterScratch, Linecap, RasterJob,
    RasterPool, Result, SceneView, Stroke, WorkControl, WorkKind,
};

fn dash_limit() -> vexel_scene::Diagnostic {
    vexel_scene::Diagnostic {
        kind: vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::DashCache),
        offset: 0,
    }
}
fn range(first: usize, end: usize) -> Result<vexel_scene::TableRange> {
    Ok(vexel_scene::TableRange {
        first,
        count: end.checked_sub(first).ok_or_else(dash_limit)?,
    })
}
struct Writer<'a> {
    job: &'a mut RasterJob,
    cache: JobDashCache,
    steps: usize,
}
impl Writer<'_> {
    fn ensure<T: vexel_scene::JobElement>(
        job: &mut RasterJob,
        handle: vexel_scene::JobBuffer<T>,
        needed: usize,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let current = job.capacity(handle)?;
        if needed <= current {
            return Ok(());
        }
        let mut capacity = if current == 0 { 32 } else { current };
        while capacity < needed {
            capacity = capacity
                .checked_add((capacity / 8).max(1))
                .ok_or_else(dash_limit)?;
        }
        job.reserve(handle, capacity, control)
    }
    fn step(&mut self, n: usize, control: &mut dyn WorkControl) -> Result<()> {
        if n > DASH_CACHE_MAX_STEPS.saturating_sub(self.steps) {
            return Err(dash_limit());
        }
        control
            .charge(WorkKind::StrokeTest, n as u64)
            .map_err(stopped)?;
        self.steps += n;
        Ok(())
    }
    fn segment(
        &mut self,
        edge: Edge,
        start_cap: Linecap,
        end_cap: Linecap,
        control: &mut dyn WorkControl,
    ) -> Result<()> {
        let needed = self
            .job
            .slice(self.cache.segments)?
            .len()
            .checked_add(1)
            .ok_or_else(dash_limit)?;
        Self::ensure(self.job, self.cache.segments, needed, control)?;
        let segment = DashSegment {
            edge,
            start_cap,
            end_cap,
        };
        self.job.extend(self.cache.segments, &[segment], control)
    }
    fn join(&mut self, a: Edge, b: Edge, control: &mut dyn WorkControl) -> Result<()> {
        let needed = self
            .job
            .slice(self.cache.joins)?
            .len()
            .checked_add(1)
            .ok_or_else(dash_limit)?;
        Self::ensure(self.job, self.cache.joins, needed, control)?;
        self.job.extend(
            self.cache.joins,
            &[DashJoin {
                previous: a.a,
                vertex: a.b,
                next: b.b,
            }],
            control,
        )
    }
}
fn dashed(
    w: &mut Writer<'_>,
    stroke: &Stroke,
    dashes: &[f64],
    edges: &[Edge],
    first: usize,
    count: usize,
    closed: bool,
    implicit: bool,
    seam: bool,
    control: &mut dyn WorkControl,
) -> Result<()> {
    let mut n = count;
    if !closed && implicit && n > 0 {
        n -= 1;
    }
    if n == 0 {
        return Ok(());
    }
    if dashes.is_empty() || dashes.len() > 16 {
        return Err(dash_limit());
    }
    let exp = dashes
        .len()
        .checked_mul(if dashes.len() % 2 == 1 { 2 } else { 1 })
        .ok_or_else(dash_limit)?;
    w.step(exp, control)?;
    let mut period = 0.0;
    for i in 0..exp {
        let d = dashes[i % dashes.len()];
        if !d.is_finite() || d <= 0.0 || !(period + d).is_finite() {
            return Err(dash_limit());
        }
        period += d;
    }
    if period <= 0.0 {
        return Err(dash_limit());
    }
    let mut phase = stroke.dash_offset % period;
    if !phase.is_finite() {
        return Err(dash_limit());
    }
    if phase < 0.0 {
        phase += period;
    }
    let mut pat = 0usize;
    for _ in 0..=exp {
        if phase < dashes[pat % dashes.len()] {
            break;
        }
        w.step(1, control)?;
        phase -= dashes[pat % dashes.len()];
        pat = (pat + 1) % exp;
    }
    let mut remain = dashes[pat % dashes.len()] - phase;
    if !remain.is_finite() || remain <= 0.0 {
        return Err(dash_limit());
    }
    let mut joins_prev = false;
    for i in 0..n {
        w.step(1, control)?;
        let e = *edges
            .get(first.checked_add(i).ok_or_else(dash_limit)?)
            .ok_or_else(dash_limit)?;
        let dx = e.b.x - e.a.x;
        let dy = e.b.y - e.a.y;
        let len = dx.hypot(dy);
        if !len.is_finite() {
            return Err(dash_limit());
        }
        if len == 0.0 {
            continue;
        }
        let (mut at, mut cont) = (0.0, false);
        while at < len {
            w.step(1, control)?;
            let take = remain.min(len - at);
            let end = at + take;
            if take <= 0.0 || !end.is_finite() {
                return Err(dash_limit());
            }
            let on = pat % 2 == 0;
            let continues = on && end == len && remain - take > 1.0e-12;
            let cross = continues && i + 1 < n;
            if on {
                let a = Point {
                    x: e.a.x + dx * (at / len),
                    y: e.a.y + dy * (at / len),
                };
                let b = Point {
                    x: e.a.x + dx * (end / len),
                    y: e.a.y + dy * (end / len),
                };
                let sc = if at == 0.0 && (joins_prev || (seam && i == 0)) {
                    Linecap::Butt
                } else {
                    stroke.cap
                };
                let ec = if cross || (end == len && seam && i + 1 == n) {
                    Linecap::Butt
                } else {
                    stroke.cap
                };
                w.segment(Edge { a, b }, sc, ec, control)?;
            }
            if cross {
                cont = true;
            }
            at = end;
            remain -= take;
            if remain <= 1.0e-12 {
                pat = (pat + 1) % exp;
                remain = dashes[pat % dashes.len()];
            }
        }
        if cont && i + 1 < n {
            w.join(
                e,
                *edges.get(first + i + 1).ok_or_else(dash_limit)?,
                control,
            )?;
        }
        joins_prev = cont;
    }
    if seam {
        w.join(
            *edges.get(first + n - 1).ok_or_else(dash_limit)?,
            *edges.get(first).ok_or_else(dash_limit)?,
            control,
        )?;
    }
    Ok(())
}
fn solid(
    w: &mut Writer<'_>,
    stroke: &Stroke,
    edges: &[Edge],
    first: usize,
    count: usize,
    closed: bool,
    implicit: bool,
    control: &mut dyn WorkControl,
) -> Result<()> {
    let mut n = count;
    if !closed && implicit && n > 0 {
        n -= 1;
    }
    if n == 0 {
        return Ok(());
    }
    for i in 0..n {
        w.step(1, control)?;
        let e = *edges
            .get(first.checked_add(i).ok_or_else(dash_limit)?)
            .ok_or_else(dash_limit)?;
        let cap = if !closed && (i == 0 || i + 1 == n) {
            stroke.cap
        } else {
            Linecap::Butt
        };
        w.segment(e, cap, cap, control)?;
    }
    let joins = if closed { n } else { n - 1 };
    for i in 0..joins {
        w.step(1, control)?;
        let next = if closed { (i + 1) % n } else { i + 1 };
        w.join(
            edges[first + (next + n - 1) % n],
            edges[first + next],
            control,
        )?;
    }
    Ok(())
}

/// Build dash records directly in the admitted same-job buffers. The returned
/// descriptor has no borrowed source or temporary cache storage.
pub fn build_dash_cache(
    view: SceneView<'_>,
    local_edges: &[Edge],
    seams: &[bool],
    job: &mut RasterJob,
    scratch: &mut JobRasterScratch,
    control: &mut dyn WorkControl,
) -> Result<JobDashCache> {
    if view.shapes.len() > 65_536 {
        return Err(vexel_scene::Diagnostic {
            kind: vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Shapes),
            offset: 0,
        });
    }
    job.validate_source(view.source_owner())?;
    // Build into new admitted buffers. The published cache remains intact until
    // dash records and every grid finish successfully; growth accounts for the
    // real old/new overlap through RasterJob's ChargeLedger admission.
    let segments = job.buffer(RasterPool::Dash, usize::MAX, control)?;
    let joins = match job.buffer(RasterPool::Dash, usize::MAX, control) {
        Ok(handle) => handle,
        Err(error) => {
            let _ = job.release(segments);
            return Err(error);
        }
    };
    let shapes = match job.buffer(RasterPool::Dash, 65_536, control) {
        Ok(handle) => handle,
        Err(error) => {
            let _ = job.release(segments);
            let _ = job.release(joins);
            return Err(error);
        }
    };
    let desc = JobDashCache {
        segments,
        joins,
        shapes,
        build_steps: 0,
    };
    if let Err(error) = job.reserve(desc.shapes, view.shapes.len(), control) {
        let _ = release_cache(job, desc);
        return Err(error);
    }
    let empty_cells = if view.shapes.is_empty() {
        None
    } else {
        match job.buffer::<vexel_scene::GridCell>(RasterPool::Grid, 0, control) {
            Ok(handle) => Some(handle),
            Err(error) => {
                let _ = release_cache(job, desc);
                return Err(error);
            }
        }
    };
    let empty_refs = if view.shapes.is_empty() {
        None
    } else {
        match job.buffer::<u32>(RasterPool::Grid, 0, control) {
            Ok(handle) => Some(handle),
            Err(error) => {
                if let Some(cells) = empty_cells {
                    let _ = job.release(cells);
                }
                let _ = release_cache(job, desc);
                return Err(error);
            }
        }
    };
    let result = (|| {
        let mut w = Writer {
            job,
            cache: desc,
            steps: 0,
        };
        for (i, shape) in view.shapes.iter().enumerate() {
            w.step(1, control)?;
            let segment_first = w.job.slice(desc.segments)?.len();
            let join_first = w.job.slice(desc.joins)?.len();
            if shape.stroke.rgba[3] != 0 && shape.stroke.width > 0.0 {
                let dashes = shape
                    .stroke
                    .dash_values
                    .slice(view.dash_values)
                    .ok_or_else(dash_limit)?;
                let subpaths = shape
                    .subpaths
                    .slice(view.path_subpaths)
                    .ok_or_else(dash_limit)?;
                if !subpaths.is_empty() {
                    for (si, sub) in subpaths.iter().enumerate() {
                        let seam = seams
                            .get(view.shapes.len() + shape.subpaths.first + si)
                            .copied()
                            .unwrap_or(false);
                        if dashes.is_empty() {
                            solid(
                                &mut w,
                                &shape.stroke,
                                local_edges,
                                sub.first_edge,
                                sub.edge_count,
                                sub.closed,
                                true,
                                control,
                            )?;
                        } else {
                            dashed(
                                &mut w,
                                &shape.stroke,
                                dashes,
                                local_edges,
                                sub.first_edge,
                                sub.edge_count,
                                sub.closed,
                                true,
                                seam,
                                control,
                            )?;
                        }
                    }
                } else {
                    let seam = seams.get(i).copied().unwrap_or(false);
                    if dashes.is_empty() {
                        solid(
                            &mut w,
                            &shape.stroke,
                            local_edges,
                            shape.edges.first,
                            shape.edges.count,
                            shape.stroke_closed,
                            shape.filled,
                            control,
                        )?;
                    } else {
                        dashed(
                            &mut w,
                            &shape.stroke,
                            dashes,
                            local_edges,
                            shape.edges.first,
                            shape.edges.count,
                            shape.stroke_closed,
                            shape.filled,
                            seam,
                            control,
                        )?;
                    }
                }
            }
            let segment_end = w.job.slice(desc.segments)?.len();
            let join_end = w.job.slice(desc.joins)?.len();
            let range = JobDashRange {
                segments: range(segment_first, segment_end)?,
                joins: range(join_first, join_end)?,
                grid_cells: empty_cells.ok_or_else(dash_limit)?,
                grid_refs: empty_refs.ok_or_else(dash_limit)?,
                grid_min_x: 0.0,
                grid_min_y: 0.0,
                grid_cell_size: 0.0,
                grid_columns: 0,
                grid_rows: 0,
            };
            w.job.extend(desc.shapes, &[range], control)?;
        }
        let cache = JobDashCache {
            build_steps: w.steps,
            ..desc
        };
        crate::job_grid::build_stroke_grid(view, w.job, cache, control)?;
        Ok(JobDashCache {
            build_steps: w.steps,
            ..desc
        })
    })();
    if let Err(error) = result {
        let _ = release_cache(job, desc);
        if let Some(handle) = empty_cells {
            let _ = job.release(handle);
        }
        if let Some(handle) = empty_refs {
            let _ = job.release(handle);
        }
        return Err(error);
    }
    let cache = result?;
    release_cache(job, scratch.dash)?;
    scratch.dash = cache;
    Ok(cache)
}

fn release_cache(job: &mut RasterJob, cache: JobDashCache) -> Result<()> {
    let mut empty = None;
    let count = job.slice(cache.shapes)?.len();
    for i in 0..count {
        let range = job.slice(cache.shapes)?[i];
        if range.grid_columns != 0 {
            job.release(range.grid_cells)?;
            job.release(range.grid_refs)?;
        } else if empty.is_none() {
            empty = Some((range.grid_cells, range.grid_refs));
        }
    }
    if let Some((cells, refs)) = empty {
        job.release(cells)?;
        job.release(refs)?;
    }
    job.release(cache.segments)?;
    job.release(cache.joins)?;
    job.release(cache.shapes)
}

pub(crate) fn tagged_index(reference: u32) -> (bool, usize) {
    (
        reference & STROKE_GRID_JOIN_BIT != 0,
        (reference & !STROKE_GRID_JOIN_BIT) as usize,
    )
}
use crate::{
    STROKE_GRID_JOIN_BIT, STROKE_GRID_MAX_AXIS, STROKE_GRID_MAX_CELLS, STROKE_GRID_MAX_REFS,
    stopped,
};
use vexel_geometry::Point;
use vexel_scene::{
    DashSegment, GridCell, JobDashCache, JobDashRange, RasterJob, RasterPool, Result, SceneView,
    WorkControl, WorkKind,
};

fn cap_error() -> vexel_scene::Diagnostic {
    vexel_scene::Diagnostic {
        kind: vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::DashCache),
        offset: 0,
    }
}
fn capacity_fallback(error: vexel_scene::Diagnostic) -> bool {
    matches!(
        error.kind,
        vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::DashCache)
            | vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Grid)
    )
}
fn bounds_segment(s: &DashSegment, radius: f64) -> [f64; 4] {
    let margin = if s.start_cap == vexel_scene::Linecap::Square
        || s.end_cap == vexel_scene::Linecap::Square
    {
        radius * std::f64::consts::SQRT_2
    } else {
        radius
    };
    [
        s.edge.a.x.min(s.edge.b.x) - margin,
        s.edge.a.y.min(s.edge.b.y) - margin,
        s.edge.a.x.max(s.edge.b.x) + margin,
        s.edge.a.y.max(s.edge.b.y) + margin,
    ]
}
fn join_bounds(p: Point, radius: f64) -> [f64; 4] {
    [p.x - radius, p.y - radius, p.x + radius, p.y + radius]
}
fn axis(x: f64, range: &JobDashRange, horizontal: bool) -> Option<usize> {
    let (origin, size, count) = if horizontal {
        (range.grid_min_x, range.grid_cell_size, range.grid_columns)
    } else {
        (range.grid_min_y, range.grid_cell_size, range.grid_rows)
    };
    let mut value = (x - origin) / size;
    if !value.is_finite() || value < -1.0 || count == 0 {
        return None;
    }
    if value < 0.0 {
        value = 0.0;
    }
    let cell = value.floor().min(count as f64 - 1.0);
    (cell >= 0.0).then_some(cell as usize)
}
fn bbox(b: [f64; 4], r: &JobDashRange) -> Option<(usize, usize, usize, usize)> {
    Some((
        axis(b[0], r, true)?,
        axis(b[1], r, false)?,
        axis(b[2], r, true)?,
        axis(b[3], r, false)?,
    ))
}
/// Build every shape grid in admitted same-job buffers. Oversized cell/ref/byte
/// grids follow the frozen scalar fallback; cancellation and admission errors
/// propagate without publishing a partially filled range.
pub(crate) fn build_stroke_grid(
    view: SceneView<'_>,
    job: &mut RasterJob,
    cache: JobDashCache,
    control: &mut dyn WorkControl,
) -> Result<()> {
    if job.slice(cache.shapes)?.len() != view.shapes.len() {
        return Err(vexel_scene::Diagnostic {
            kind: vexel_scene::ErrorKind::InvalidArgument,
            offset: 0,
        });
    }
    let mut total_cells = 0usize;
    let mut total_refs = 0usize;
    for i in 0..view.shapes.len() {
        control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
        let mut range = *job.slice(cache.shapes)?.get(i).ok_or_else(cap_error)?;
        range.grid_min_x = 0.0;
        range.grid_min_y = 0.0;
        range.grid_cell_size = 0.0;
        range.grid_columns = 0;
        range.grid_rows = 0;
        let primitive = range
            .segments
            .count
            .checked_add(range.joins.count)
            .ok_or_else(cap_error)?;
        if primitive == 0 {
            job.slice_mut(cache.shapes)?[i] = range;
            continue;
        }
        let shape = &view.shapes[i];
        let radius = shape.stroke.width * 0.5;
        let mut minx = f64::INFINITY;
        let mut miny = f64::INFINITY;
        let mut maxx = f64::NEG_INFINITY;
        let mut maxy = f64::NEG_INFINITY;
        let sr = range.segments.first..range.segments.end().ok_or_else(cap_error)?;
        let jr = range.joins.first..range.joins.end().ok_or_else(cap_error)?;
        if sr.end > job.slice(cache.segments)?.len() || jr.end > job.slice(cache.joins)?.len() {
            return Err(vexel_scene::Diagnostic {
                kind: vexel_scene::ErrorKind::InvalidArgument,
                offset: 0,
            });
        }
        for index in sr.clone() {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            let seg = job.slice(cache.segments)?[index];
            let b = bounds_segment(&seg, radius);
            minx = minx.min(b[0]);
            miny = miny.min(b[1]);
            maxx = maxx.max(b[2]);
            maxy = maxy.max(b[3]);
        }
        let jradii = if shape.stroke.join == vexel_scene::Linejoin::Miter {
            radius * shape.stroke.miter_limit
        } else {
            radius
        };
        for index in jr.clone() {
            control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
            let j = job.slice(cache.joins)?[index];
            let b = join_bounds(j.vertex, jradii);
            minx = minx.min(b[0]);
            miny = miny.min(b[1]);
            maxx = maxx.max(b[2]);
            maxy = maxy.max(b[3]);
        }
        let sx = maxx - minx;
        let sy = maxy - miny;
        if !sx.is_finite() || !sy.is_finite() {
            job.slice_mut(cache.shapes)?[i] = range;
            continue;
        }
        let size = 1.0f64.max(sx.max(sy) / STROKE_GRID_MAX_AXIS as f64);
        let cols = (sx / size).ceil().max(1.0);
        let rows = (sy / size).ceil().max(1.0);
        if cols > 128.0 || rows > 128.0 {
            job.slice_mut(cache.shapes)?[i] = range;
            continue;
        }
        range.grid_min_x = minx;
        range.grid_min_y = miny;
        range.grid_cell_size = size;
        range.grid_columns = cols as u16;
        range.grid_rows = rows as u16;
        let cell_count = (cols as usize)
            .checked_mul(rows as usize)
            .ok_or_else(cap_error)?;
        if total_cells
            .checked_add(cell_count)
            .is_none_or(|n| n > STROKE_GRID_MAX_CELLS)
        {
            range.grid_columns = 0;
            range.grid_rows = 0;
            job.slice_mut(cache.shapes)?[i] = range;
            continue;
        }
        let cells_handle =
            job.buffer::<GridCell>(RasterPool::Grid, STROKE_GRID_MAX_CELLS, control)?;
        let mut refs_handle = None;
        let built = (|| -> Result<Option<(vexel_scene::JobBuffer<u32>, usize)>> {
            if let Err(error) = job.reserve(cells_handle, cell_count, control) {
                if capacity_fallback(error) {
                    return Ok(None);
                }
                return Err(error);
            }
            let zero = GridCell { first: 0, count: 0 };
            for _ in 0..cell_count {
                job.extend(cells_handle, &[zero], control)?;
            }
            let mut count = 0usize;
            let mut fits = true;
            for p in 0..primitive {
                control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                let b = if p < range.segments.count {
                    let seg = job.slice(cache.segments)?[range.segments.first + p];
                    bounds_segment(&seg, radius)
                } else {
                    let join =
                        job.slice(cache.joins)?[range.joins.first + p - range.segments.count];
                    join_bounds(join.vertex, jradii)
                };
                if p < range.segments.count
                    && ![b[0], b[1], b[2], b[3]].into_iter().all(f64::is_finite)
                {
                    fits = false;
                    break;
                }
                let Some((x0, y0, x1, y1)) = bbox(b, &range) else {
                    fits = false;
                    break;
                };
                for cy in y0..=y1 {
                    for cx in x0..=x1 {
                        control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                        let index = cy * cols as usize + cx;
                        let next = job.slice(cells_handle)?[index]
                            .count
                            .checked_add(1)
                            .ok_or_else(cap_error)?;
                        job.slice_mut(cells_handle)?[index].count = next;
                        count = count.checked_add(1).ok_or_else(cap_error)?;
                    }
                }
            }
            if !fits
                || total_refs
                    .checked_add(count)
                    .is_none_or(|n| n > STROKE_GRID_MAX_REFS)
            {
                return Ok(None);
            }
            let refs = job.buffer::<u32>(RasterPool::Grid, STROKE_GRID_MAX_REFS, control)?;
            refs_handle = Some(refs);
            if let Err(error) = job.reserve(refs, count, control) {
                if capacity_fallback(error) {
                    return Ok(None);
                }
                return Err(error);
            }
            for _ in 0..count {
                job.extend(refs, &[0u32], control)?;
            }
            let mut offset = 0usize;
            for cell in job.slice_mut(cells_handle)? {
                let n = cell.count;
                cell.first = offset;
                cell.count = 0;
                offset = offset.checked_add(n).ok_or_else(cap_error)?;
            }
            for p in 0..primitive {
                control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                let b = if p < range.segments.count {
                    let seg = job.slice(cache.segments)?[range.segments.first + p];
                    bounds_segment(&seg, radius)
                } else {
                    let join =
                        job.slice(cache.joins)?[range.joins.first + p - range.segments.count];
                    join_bounds(join.vertex, jradii)
                };
                let (x0, y0, x1, y1) = bbox(b, &range).ok_or_else(cap_error)?;
                let encoded = if p < range.segments.count {
                    let index = range.segments.first + p;
                    if index >= STROKE_GRID_JOIN_BIT as usize {
                        return Err(cap_error());
                    }
                    u32::try_from(index).map_err(|_| cap_error())?
                } else {
                    let index = range.joins.first + p - range.segments.count;
                    if index >= STROKE_GRID_JOIN_BIT as usize {
                        return Err(cap_error());
                    }
                    STROKE_GRID_JOIN_BIT | index as u32
                };
                for cy in y0..=y1 {
                    for cx in x0..=x1 {
                        control.charge(WorkKind::StrokeTest, 1).map_err(stopped)?;
                        let cell_index = cy * cols as usize + cx;
                        let cell = job.slice(cells_handle)?[cell_index];
                        let ref_index = cell.first.checked_add(cell.count).ok_or_else(cap_error)?;
                        job.slice_mut(refs)?[ref_index] = encoded;
                        job.slice_mut(cells_handle)?[cell_index].count += 1;
                    }
                }
            }
            Ok(Some((refs, count)))
        })();
        match built {
            Ok(Some((refs, count))) => {
                range.grid_cells = cells_handle;
                range.grid_refs = refs;
                total_cells += cell_count;
                total_refs += count;
                job.slice_mut(cache.shapes)?[i] = range;
            }
            Ok(None) => {
                if let Some(refs) = refs_handle {
                    job.release(refs)?;
                }
                job.release(cells_handle)?;
                range.grid_columns = 0;
                range.grid_rows = 0;
                job.slice_mut(cache.shapes)?[i] = range;
            }
            Err(error) => {
                if let Some(refs) = refs_handle {
                    let _ = job.release(refs);
                }
                let _ = job.release(cells_handle);
                return Err(error);
            }
        }
    }
    Ok(())
}

#include "shape_render_internal.h"

#include <math.h>
#include <stdlib.h>

static bool dash_range_joins_seam(const svg_shape_stroke *stroke,
                                  const double *dash_values,
                                  const geom_edge *edges, size_t first,
                                  size_t count)
{
    if (stroke->dash_count == 0U || count == 0U || dash_values == NULL)
        return false;
    size_t expanded = stroke->dash_count +
        (stroke->dash_count & 1U ? stroke->dash_count : 0U);
    double period = 0.0;
    for (size_t i = 0U; i < expanded; ++i)
        period += dash_values[i % stroke->dash_count];
    if (!isfinite(period) || period <= 0.0) return false;
    double phase = fmod(stroke->dash_offset, period);
    if (phase < 0.0) phase += period;
    size_t pattern = 0U;
    while (phase >= dash_values[pattern % stroke->dash_count]) {
        phase -= dash_values[pattern % stroke->dash_count];
        pattern = (pattern + 1U) % expanded;
    }
    bool starts_on = (pattern & 1U) == 0U;
    double remain = dash_values[pattern % stroke->dash_count] - phase;
    bool ends_on = false;
    for (size_t i = 0U; i < count; ++i) {
        geom_edge edge = edges[first + i];
        double length = hypot(edge.b.x-edge.a.x, edge.b.y-edge.a.y);
        while (length > 0.0) {
            double step = fmin(remain, length);
            ends_on = (pattern & 1U) == 0U;
            length -= step;
            remain -= step;
            if (remain <= RASTER_STROKE_DASH_EPSILON) {
                pattern = (pattern + 1U) % expanded;
                remain = dash_values[pattern % stroke->dash_count];
            }
        }
    }
    return starts_on && ends_on;
}

bool raster_shape_dash_subpath_joins_closed_seam(
    const svg_shape_document *doc, size_t shape, size_t subpath,
    const geom_edge *edges)
{
    const svg_shape_stroke *stroke = &doc->strokes[shape];
    if (doc->shape_subpath_count == NULL ||
        subpath >= doc->shape_subpath_count[shape]) return false;
    const svg_shape_path_subpath *path = &doc->path_subpaths[
        doc->shape_subpath_start[shape] + subpath];
    if (!path->closed) return false;
    return dash_range_joins_seam(stroke,
                                 svg_shape_stroke_dash_values_for_shape(
                                     doc, shape), edges, path->first_edge,
                                 path->edge_count);
}

bool raster_shape_dash_joins_closed_seam(const svg_shape_document *doc, size_t shape,
                                         const geom_edge *edges)
{
    const svg_shape_stroke *stroke = &doc->strokes[shape];
    size_t subpath_count = doc->shape_subpath_count == NULL ? 0U :
                           doc->shape_subpath_count[shape];
    if (subpath_count != 0U) {
        for (size_t i = 0U; i < subpath_count; ++i)
            if (raster_shape_dash_subpath_joins_closed_seam(doc, shape, i, edges))
                return true;
        return false;
    }
    if (!doc->shape_stroke_closed[shape]) return false;
    return dash_range_joins_seam(stroke,
                                 svg_shape_stroke_dash_values_for_shape(
                                     doc, shape), edges,
                                 doc->shape_edge_start[shape],
                                 doc->shape_edge_count[shape]);
}

static bool dash_size_add(size_t left, size_t right, size_t *out)
{
    if (right > SIZE_MAX - left) return false;
    *out = left + right;
    return true;
}

static bool dash_size_mul(size_t left, size_t right, size_t *out)
{
    if (left != 0U && right > SIZE_MAX / left) return false;
    *out = left * right;
    return true;
}

static bool dash_cache_capacity(size_t current, size_t needed,
                               size_t *out_capacity)
{
    size_t capacity = current == 0U ? 32U : current;
    while (capacity < needed) {
        size_t growth = capacity / 8U;
        if (growth == 0U) growth = 1U;
        if (growth > SIZE_MAX - capacity) return false;
        capacity += growth;
    }
    *out_capacity = capacity;
    return true;
}

static bool dash_cache_bytes_fit(const raster_shape_dash_cache *cache,
                                 size_t segment_capacity,
                                 size_t join_capacity)
{
    size_t range_bytes, segment_bytes, join_bytes, total;
    return cache->shape_count <= SIZE_MAX / sizeof(*cache->shapes) &&
        dash_size_mul(cache->shape_count, sizeof(*cache->shapes), &range_bytes) &&
        dash_size_mul(segment_capacity, sizeof(*cache->segments), &segment_bytes) &&
        dash_size_mul(join_capacity, sizeof(*cache->joins), &join_bytes) &&
        dash_size_add(range_bytes, segment_bytes, &total) &&
        dash_size_add(total, join_bytes, &total) &&
        dash_size_add(total, cache->grid_bytes, &total) &&
        total <= RASTER_DASH_CACHE_BYTE_LIMIT;
}

static bool dash_cache_reserve_segments(raster_shape_dash_cache *cache,
                                        size_t needed,
                                        svg_shape_diagnostic *diagnostic)
{
    if (needed <= cache->segment_capacity) return true;
    size_t capacity;
    if (!dash_cache_capacity(cache->segment_capacity, needed, &capacity)) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    if (!dash_cache_bytes_fit(cache, capacity, cache->join_capacity)) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    raster_dash_segment *segments = realloc(cache->segments,
        capacity * sizeof(*segments));
    if (segments == NULL) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0U};
        return false;
    }
    cache->segments = segments;
    cache->segment_capacity = capacity;
    return true;
}

static bool dash_cache_reserve_joins(raster_shape_dash_cache *cache,
                                     size_t needed,
                                     svg_shape_diagnostic *diagnostic)
{
    if (needed <= cache->join_capacity) return true;
    size_t capacity;
    if (!dash_cache_capacity(cache->join_capacity, needed, &capacity)) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    if (!dash_cache_bytes_fit(cache, cache->segment_capacity, capacity)) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    raster_dash_join *joins = realloc(cache->joins, capacity * sizeof(*joins));
    if (joins == NULL) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0U};
        return false;
    }
    cache->joins = joins;
    cache->join_capacity = capacity;
    return true;
}

static bool dash_cache_add_step(raster_shape_dash_cache *cache, size_t amount,
                                svg_shape_diagnostic *diagnostic)
{
    if (amount > RASTER_DASH_CACHE_MAX_STEPS - cache->build_steps) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    cache->build_steps += amount;
    return true;
}

static bool dash_cache_add_segment(raster_shape_dash_cache *cache,
                                   geom_point a, geom_point b,
                                   svg_shape_linecap start_cap,
                                   svg_shape_linecap end_cap,
                                   svg_shape_diagnostic *diagnostic)
{
    size_t needed;
    if (!dash_size_add(cache->segment_count, 1U, &needed) ||
        !dash_cache_reserve_segments(cache, needed, diagnostic)) return false;
    cache->segments[cache->segment_count++] = (raster_dash_segment){
        .edge = {a, b}, .start_cap = start_cap, .end_cap = end_cap};
    return true;
}

static bool dash_cache_add_join(raster_shape_dash_cache *cache,
                                geom_edge previous, geom_edge next,
                                svg_shape_diagnostic *diagnostic)
{
    size_t needed;
    if (!dash_size_add(cache->join_count, 1U, &needed) ||
        !dash_cache_reserve_joins(cache, needed, diagnostic)) return false;
    cache->joins[cache->join_count++] = (raster_dash_join){
        .previous = previous.a, .vertex = previous.b, .next = next.b};
    return true;
}

static bool dash_cache_build_range(raster_shape_dash_cache *cache,
                                   const svg_shape_stroke *stroke,
                                   const double *dash_values,
                                   const geom_edge *edges, size_t first,
                                   size_t count, bool closed,
                                   bool implicit_close, bool dash_seam,
                                   svg_shape_diagnostic *diagnostic)
{
    if (!closed && implicit_close && count != 0U) count--;
    if (count == 0U) return true;
    if (edges == NULL || dash_values == NULL || stroke->dash_count == 0U ||
        stroke->dash_count > SVG_SHAPE_MAX_DASH_VALUES) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    size_t pattern_count = stroke->dash_count;
    size_t expanded_count = pattern_count +
        ((pattern_count & 1U) != 0U ? pattern_count : 0U);
    double period = 0.0;
    if (!dash_cache_add_step(cache, expanded_count, diagnostic)) return false;
    for (size_t index = 0U; index < expanded_count; ++index) {
        double interval = dash_values[index % pattern_count];
        if (!isfinite(interval) || interval <= 0.0 ||
            !isfinite(period + interval)) {
            if (diagnostic != NULL)
                *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
            return false;
        }
        period += interval;
    }
    if (period <= 0.0) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    double phase = fmod(stroke->dash_offset, period);
    if (!isfinite(phase)) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    if (phase < 0.0) phase += period;
    size_t pattern = 0U;
    size_t pattern_advances = 0U;
    while (phase >= dash_values[pattern % pattern_count]) {
        if (pattern_advances++ >= expanded_count ||
            !dash_cache_add_step(cache, 1U, diagnostic)) {
            if (diagnostic != NULL && diagnostic->category == SVG_SHAPE_ERROR_NONE)
                *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
            return false;
        }
        phase -= dash_values[pattern % pattern_count];
        pattern = (pattern + 1U) % expanded_count;
    }
    double remain = dash_values[pattern % pattern_count] - phase;
    if (!isfinite(remain) || remain <= 0.0) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    bool joins_from_previous = false;
    for (size_t edge_index = 0U; edge_index < count; ++edge_index) {
        if (!dash_cache_add_step(cache, 1U, diagnostic)) return false;
        geom_edge edge = edges[first + edge_index];
        double dx = edge.b.x - edge.a.x;
        double dy = edge.b.y - edge.a.y;
        double length = hypot(dx, dy);
        if (!isfinite(length)) {
            if (diagnostic != NULL)
                *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
            return false;
        }
        if (length == 0.0) continue;
        double at = 0.0;
        bool continues_at_vertex = false;
        while (at < length) {
            if (!dash_cache_add_step(cache, 1U, diagnostic)) return false;
            double step = fmin(remain, length - at);
            double end = at + step;
            if (!(step > 0.0) || !isfinite(end)) {
                if (diagnostic != NULL)
                    *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
                return false;
            }
            bool on = (pattern & 1U) == 0U;
            bool continues = on && end == length &&
                remain - step > RASTER_STROKE_DASH_EPSILON;
            bool crosses_vertex = continues && edge_index + 1U < count;
            if (on) {
                geom_point a = {edge.a.x + dx * (at / length),
                                edge.a.y + dy * (at / length)};
                geom_point b = {edge.a.x + dx * (end / length),
                                edge.a.y + dy * (end / length)};
                bool starts_at_join = at == 0.0 &&
                    (joins_from_previous || (dash_seam && edge_index == 0U));
                bool ends_at_seam = end == length && dash_seam &&
                    edge_index + 1U == count;
                svg_shape_linecap start_cap = starts_at_join ?
                    SVG_SHAPE_CAP_BUTT : stroke->cap;
                svg_shape_linecap end_cap = (crosses_vertex || ends_at_seam) ?
                    SVG_SHAPE_CAP_BUTT : stroke->cap;
                if (!dash_cache_add_segment(cache, a, b, start_cap, end_cap,
                                            diagnostic)) return false;
            }
            if (crosses_vertex) continues_at_vertex = true;
            at = end;
            remain -= step;
            if (remain <= RASTER_STROKE_DASH_EPSILON) {
                pattern = (pattern + 1U) % expanded_count;
                remain = dash_values[pattern % pattern_count];
            }
        }
        if (continues_at_vertex && edge_index + 1U < count &&
            !dash_cache_add_join(cache, edge, edges[first + edge_index + 1U],
                                 diagnostic)) return false;
        joins_from_previous = continues_at_vertex;
    }
    if (dash_seam &&
        !dash_cache_add_join(cache, edges[first + count - 1U], edges[first],
                             diagnostic)) return false;
    return true;
}

static bool dash_cache_build_solid_range(raster_shape_dash_cache *cache,
                                         const svg_shape_stroke *stroke,
                                         const geom_edge *edges, size_t first,
                                         size_t count, bool closed,
                                         bool implicit_close,
                                         svg_shape_diagnostic *diagnostic)
{
    if (!closed && implicit_close && count != 0U) count--;
    if (count == 0U) return true;
    if (edges == NULL) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    for (size_t index = 0U; index < count; ++index) {
        if (!dash_cache_add_step(cache, 1U, diagnostic)) return false;
        svg_shape_linecap cap = (!closed &&
            (index == 0U || index + 1U == count)) ? stroke->cap :
            SVG_SHAPE_CAP_BUTT;
        geom_edge edge = edges[first + index];
        if (!dash_cache_add_segment(cache, edge.a, edge.b, cap, cap, diagnostic))
            return false;
    }
    size_t join_count = closed ? count : count - 1U;
    for (size_t index = 0U; index < join_count; ++index) {
        if (!dash_cache_add_step(cache, 1U, diagnostic)) return false;
        size_t next = closed ? (index + 1U) % count : index + 1U;
        geom_edge previous = edges[first + (next + count - 1U) % count];
        geom_edge following = edges[first + next];
        if (!dash_cache_add_join(cache, previous, following, diagnostic))
            return false;
    }
    return true;
}

void raster_shape_dash_cache_destroy(raster_shape_dash_cache *cache)
{
    if (cache == NULL) return;
    if (cache->shapes != NULL) {
        for (size_t shape = 0U; shape < cache->shape_count; ++shape) {
            free(cache->shapes[shape].grid_cells);
            free(cache->shapes[shape].grid_refs);
        }
    }
    free(cache->segments);
    free(cache->joins);
    free(cache->shapes);
    *cache = (raster_shape_dash_cache){0};
}

bool raster_shape_dash_cache_create(const svg_shape_document *doc,
                                    const geom_edge *local_edges,
                                    const bool *dash_seams,
                                    raster_shape_dash_cache *out_cache,
                                    svg_shape_diagnostic *diagnostic)
{
    if (out_cache == NULL || doc == NULL) return false;
    *out_cache = (raster_shape_dash_cache){0};
    out_cache->shape_count = doc->shape_count;
    if (doc->shape_count == 0U) return true;
    size_t range_bytes;
    if (!dash_size_mul(doc->shape_count, sizeof(*out_cache->shapes),
                       &range_bytes) || range_bytes > RASTER_DASH_CACHE_BYTE_LIMIT) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_LIMIT, 0U};
        return false;
    }
    out_cache->shapes = calloc(doc->shape_count, sizeof(*out_cache->shapes));
    if (out_cache->shapes == NULL) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0U};
        return false;
    }
    for (size_t shape = 0U; shape < doc->shape_count; ++shape) {
        raster_dash_shape_range *range = &out_cache->shapes[shape];
        range->segment_first = out_cache->segment_count;
        range->join_first = out_cache->join_count;
        const svg_shape_stroke *stroke = &doc->strokes[shape];
        if (stroke->rgba[3] != 0U && stroke->width > 0.0) {
            bool dashed = stroke->dash_count != 0U;
            const double *dash_values =
                svg_shape_stroke_dash_values_for_shape(doc, shape);
            if (dashed && dash_values == NULL) {
                if (diagnostic != NULL)
                    *diagnostic = (svg_shape_diagnostic){
                        SVG_SHAPE_ERROR_LIMIT, 0U};
                goto fail;
            }
            if (doc->shape_subpath_count[shape] != 0U) {
                size_t first_subpath = doc->shape_subpath_start[shape];
                size_t subpath_count = doc->shape_subpath_count[shape];
                for (size_t index = 0U; index < subpath_count; ++index) {
                    size_t subpath = first_subpath + index;
                    const svg_shape_path_subpath *path = &doc->path_subpaths[subpath];
                    bool seam = dash_seams != NULL &&
                        dash_seams[doc->shape_count + subpath];
                    bool built = dashed ?
                        dash_cache_build_range(out_cache, stroke, dash_values,
                            local_edges,
                            path->first_edge, path->edge_count, path->closed,
                            true, seam, diagnostic) :
                        dash_cache_build_solid_range(out_cache, stroke, local_edges,
                            path->first_edge, path->edge_count, path->closed,
                            true, diagnostic);
                    if (!built) goto fail;
                }
            } else {
                bool seam = dash_seams != NULL && dash_seams[shape];
                bool built = dashed ?
                    dash_cache_build_range(out_cache, stroke, dash_values,
                        local_edges,
                        doc->shape_edge_start[shape], doc->shape_edge_count[shape],
                        doc->shape_stroke_closed[shape], doc->shape_filled[shape],
                        seam, diagnostic) :
                    dash_cache_build_solid_range(out_cache, stroke, local_edges,
                        doc->shape_edge_start[shape], doc->shape_edge_count[shape],
                        doc->shape_stroke_closed[shape], doc->shape_filled[shape],
                        diagnostic);
                if (!built) goto fail;
            }
        }
        range->segment_count = out_cache->segment_count - range->segment_first;
        range->join_count = out_cache->join_count - range->join_first;
    }
    if (!raster_shape_stroke_grid_build(doc, out_cache, diagnostic)) goto fail;
    return true;

fail:
    raster_shape_dash_cache_destroy(out_cache);
    return false;
}
#include "shape_render_internal.h"

#include <math.h>
#include <stdlib.h>

#define RASTER_STROKE_GRID_JOIN_BIT UINT32_C(0x80000000)

static bool add_size(size_t left, size_t right, size_t *out)
{
    if (right > SIZE_MAX - left) return false;
    *out = left + right;
    return true;
}

static bool mul_size(size_t left, size_t right, size_t *out)
{
    if (left != 0U && right > SIZE_MAX / left) return false;
    *out = left * right;
    return true;
}

static bool grid_bytes_fit(const raster_shape_dash_cache *cache, size_t extra)
{
    size_t shapes, segments, joins, used;
    return mul_size(cache->shape_count, sizeof(*cache->shapes), &shapes) &&
        mul_size(cache->segment_capacity, sizeof(*cache->segments), &segments) &&
        mul_size(cache->join_capacity, sizeof(*cache->joins), &joins) &&
        add_size(shapes, segments, &used) && add_size(used, joins, &used) &&
        add_size(used, cache->grid_bytes, &used) && add_size(used, extra, &used) &&
        used <= RASTER_DASH_CACHE_BYTE_LIMIT;
}

static double segment_margin(const raster_dash_segment *segment, double radius)
{
    return segment->start_cap == SVG_SHAPE_CAP_SQUARE ||
           segment->end_cap == SVG_SHAPE_CAP_SQUARE ? radius * 1.4142135623730951 :
           radius;
}

static double join_margin(const svg_shape_stroke *stroke)
{
    double radius = stroke->width * 0.5;
    return stroke->join == SVG_SHAPE_JOIN_MITER ? radius * stroke->miter_limit : radius;
}

static bool grid_axis_cell(double coordinate, double origin, double cell_size,
                           uint16_t count, uint16_t *out)
{
    double offset = (coordinate - origin) / cell_size;
    if (!isfinite(offset) || offset < -1.0) return false;
    if (offset < 0.0) offset = 0.0;
    double cell = floor(offset);
    if (cell >= (double)count) cell = (double)count - 1.0;
    if (cell < 0.0) return false;
    *out = (uint16_t)cell;
    return true;
}

static bool bbox_cells(const raster_dash_shape_range *range,
                       double min_x, double min_y, double max_x, double max_y,
                       uint16_t *x_first, uint16_t *y_first,
                       uint16_t *x_last, uint16_t *y_last)
{
    return grid_axis_cell(min_x, range->grid_min_x, range->grid_cell_size,
                          range->grid_columns, x_first) &&
        grid_axis_cell(min_y, range->grid_min_y, range->grid_cell_size,
                       range->grid_rows, y_first) &&
        grid_axis_cell(max_x, range->grid_min_x, range->grid_cell_size,
                       range->grid_columns, x_last) &&
        grid_axis_cell(max_y, range->grid_min_y, range->grid_cell_size,
                       range->grid_rows, y_last) &&
        *x_first <= *x_last && *y_first <= *y_last;
}

static bool segment_bbox(const raster_dash_segment *segment, double radius,
                         double *min_x, double *min_y,
                         double *max_x, double *max_y)
{
    double margin = segment_margin(segment, radius);
    *min_x = fmin(segment->edge.a.x, segment->edge.b.x) - margin;
    *min_y = fmin(segment->edge.a.y, segment->edge.b.y) - margin;
    *max_x = fmax(segment->edge.a.x, segment->edge.b.x) + margin;
    *max_y = fmax(segment->edge.a.y, segment->edge.b.y) + margin;
    return isfinite(*min_x) && isfinite(*min_y) &&
           isfinite(*max_x) && isfinite(*max_y);
}

static bool join_bbox(const raster_dash_join *join, double margin,
                      double *min_x, double *min_y,
                      double *max_x, double *max_y)
{
    *min_x = join->vertex.x - margin;
    *min_y = join->vertex.y - margin;
    *max_x = join->vertex.x + margin;
    *max_y = join->vertex.y + margin;
    return isfinite(*min_x) && isfinite(*min_y) &&
           isfinite(*max_x) && isfinite(*max_y);
}

static bool add_bbox_references(const raster_dash_shape_range *range,
                                raster_stroke_grid_cell *cells,
                                double min_x, double min_y,
                                double max_x, double max_y,
                                size_t *total)
{
    uint16_t x_first, y_first, x_last, y_last;
    if (!bbox_cells(range, min_x, min_y, max_x, max_y,
                    &x_first, &y_first, &x_last, &y_last)) return false;
    for (uint16_t y = y_first; y <= y_last; ++y) {
        for (uint16_t x = x_first; x <= x_last; ++x) {
            raster_stroke_grid_cell *cell = &cells[(size_t)y * range->grid_columns + x];
            if (cell->count == SIZE_MAX || *total == SIZE_MAX) return false;
            cell->count++;
            (*total)++;
        }
    }
    return true;
}

static bool fill_bbox_references(const raster_dash_shape_range *range,
                                 raster_stroke_grid_cell *cells,
                                 uint32_t *refs, uint32_t encoded,
                                 double min_x, double min_y,
                                 double max_x, double max_y)
{
    uint16_t x_first, y_first, x_last, y_last;
    if (!bbox_cells(range, min_x, min_y, max_x, max_y,
                    &x_first, &y_first, &x_last, &y_last)) return false;
    for (uint16_t y = y_first; y <= y_last; ++y) {
        for (uint16_t x = x_first; x <= x_last; ++x) {
            raster_stroke_grid_cell *cell = &cells[(size_t)y * range->grid_columns + x];
            if (cell->first > range->grid_ref_count ||
                cell->count >= range->grid_ref_count - cell->first) return false;
            refs[cell->first + cell->count++] = encoded;
        }
    }
    return true;
}

static void abandon_grid(raster_shape_dash_cache *cache,
                         raster_dash_shape_range *range,
                         raster_stroke_grid_cell *cells,
                         size_t cell_count)
{
    free(cells);
    range->grid_cells = NULL;
    range->grid_refs = NULL;
    range->grid_columns = 0U;
    range->grid_rows = 0U;
    range->grid_cell_count = 0U;
    range->grid_ref_count = 0U;
    cache->grid_cell_count -= cell_count;
}

static bool build_shape_grid(raster_shape_dash_cache *cache, size_t shape,
                             const svg_shape_stroke *stroke,
                             svg_shape_diagnostic *diagnostic)
{
    raster_dash_shape_range *range = &cache->shapes[shape];
    size_t primitive_count;
    if (!add_size(range->segment_count, range->join_count, &primitive_count) ||
        primitive_count == 0U) return true;
    double radius = stroke->width * 0.5;
    double min_x = INFINITY, min_y = INFINITY, max_x = -INFINITY, max_y = -INFINITY;
    for (size_t index = 0U; index < range->segment_count; ++index) {
        double item_min_x, item_min_y, item_max_x, item_max_y;
        const raster_dash_segment *segment =
            &cache->segments[range->segment_first + index];
        if (!segment_bbox(segment, radius, &item_min_x, &item_min_y,
                          &item_max_x, &item_max_y)) return true;
        min_x = fmin(min_x, item_min_x);
        min_y = fmin(min_y, item_min_y);
        max_x = fmax(max_x, item_max_x);
        max_y = fmax(max_y, item_max_y);
    }
    double join_reach = join_margin(stroke);
    for (size_t index = 0U; index < range->join_count; ++index) {
        double item_min_x, item_min_y, item_max_x, item_max_y;
        const raster_dash_join *join = &cache->joins[range->join_first + index];
        if (!join_bbox(join, join_reach, &item_min_x, &item_min_y,
                       &item_max_x, &item_max_y)) return true;
        min_x = fmin(min_x, item_min_x);
        min_y = fmin(min_y, item_min_y);
        max_x = fmax(max_x, item_max_x);
        max_y = fmax(max_y, item_max_y);
    }
    double span_x = max_x - min_x, span_y = max_y - min_y;
    if (!isfinite(span_x) || !isfinite(span_y) || span_x < 0.0 || span_y < 0.0)
        return true;
    double cell_size = fmax(RASTER_STROKE_GRID_CELL_SIZE,
        fmax(span_x, span_y) / (double)RASTER_STROKE_GRID_MAX_AXIS);
    if (!isfinite(cell_size) || cell_size <= 0.0) return true;
    double columns_value = ceil(span_x / cell_size);
    double rows_value = ceil(span_y / cell_size);
    if (columns_value < 1.0) columns_value = 1.0;
    if (rows_value < 1.0) rows_value = 1.0;
    if (columns_value > RASTER_STROKE_GRID_MAX_AXIS ||
        rows_value > RASTER_STROKE_GRID_MAX_AXIS) return true;
    range->grid_min_x = min_x;
    range->grid_min_y = min_y;
    range->grid_cell_size = cell_size;
    range->grid_columns = (uint16_t)columns_value;
    range->grid_rows = (uint16_t)rows_value;
    size_t cell_count;
    if (!mul_size(range->grid_columns, range->grid_rows, &cell_count) ||
        cell_count > RASTER_STROKE_GRID_MAX_CELLS - cache->grid_cell_count)
        return true;
    size_t cell_bytes;
    if (!mul_size(cell_count, sizeof(raster_stroke_grid_cell), &cell_bytes) ||
        !grid_bytes_fit(cache, cell_bytes)) return true;
    raster_stroke_grid_cell *cells = calloc(cell_count, sizeof(*cells));
    if (cells == NULL) {
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0U};
        return false;
    }
    cache->grid_cell_count += cell_count;
    range->grid_cell_count = cell_count;
    range->grid_cells = cells;
    size_t reference_count = 0U;
    bool references_fit = true;
    for (size_t index = 0U; index < range->segment_count && references_fit; ++index) {
        double item_min_x, item_min_y, item_max_x, item_max_y;
        const raster_dash_segment *segment =
            &cache->segments[range->segment_first + index];
        references_fit = segment_bbox(segment, radius, &item_min_x, &item_min_y,
                                      &item_max_x, &item_max_y) &&
            add_bbox_references(range, cells, item_min_x, item_min_y,
                                item_max_x, item_max_y, &reference_count);
    }
    for (size_t index = 0U; index < range->join_count && references_fit; ++index) {
        double item_min_x, item_min_y, item_max_x, item_max_y;
        const raster_dash_join *join = &cache->joins[range->join_first + index];
        references_fit = join_bbox(join, join_reach, &item_min_x, &item_min_y,
                                   &item_max_x, &item_max_y) &&
            add_bbox_references(range, cells, item_min_x, item_min_y,
                                item_max_x, item_max_y, &reference_count);
    }
    if (!references_fit ||
        reference_count > RASTER_STROKE_GRID_MAX_REFS - cache->grid_ref_count) {
        abandon_grid(cache, range, cells, cell_count);
        return true;
    }
    size_t ref_bytes, allocation_bytes;
    if (!mul_size(reference_count, sizeof(*range->grid_refs), &ref_bytes) ||
        !add_size(cell_bytes, ref_bytes, &allocation_bytes) ||
        !grid_bytes_fit(cache, allocation_bytes)) {
        abandon_grid(cache, range, cells, cell_count);
        return true;
    }
    uint32_t *refs = malloc(ref_bytes == 0U ? 1U : ref_bytes);
    if (refs == NULL) {
        abandon_grid(cache, range, cells, cell_count);
        if (diagnostic != NULL)
            *diagnostic = (svg_shape_diagnostic){SVG_SHAPE_ERROR_OOM, 0U};
        return false;
    }
    size_t first = 0U;
    for (size_t index = 0U; index < cell_count; ++index) {
        size_t count = cells[index].count;
        cells[index].first = first;
        cells[index].count = 0U;
        if (!add_size(first, count, &first)) {
            free(refs);
            abandon_grid(cache, range, cells, cell_count);
            return true;
        }
    }
    range->grid_refs = refs;
    range->grid_ref_count = reference_count;
    for (size_t index = 0U; index < range->segment_count; ++index) {
        double item_min_x, item_min_y, item_max_x, item_max_y;
        const raster_dash_segment *segment =
            &cache->segments[range->segment_first + index];
        if (!segment_bbox(segment, radius, &item_min_x, &item_min_y,
                          &item_max_x, &item_max_y) ||
            !fill_bbox_references(range, cells, refs,
                (uint32_t)(range->segment_first + index),
                item_min_x, item_min_y, item_max_x, item_max_y)) {
            abandon_grid(cache, range, cells, cell_count);
            free(refs);
            return true;
        }
    }
    for (size_t index = 0U; index < range->join_count; ++index) {
        double item_min_x, item_min_y, item_max_x, item_max_y;
        const raster_dash_join *join = &cache->joins[range->join_first + index];
        if (!join_bbox(join, join_reach, &item_min_x, &item_min_y,
                       &item_max_x, &item_max_y) ||
            !fill_bbox_references(range, cells, refs,
                RASTER_STROKE_GRID_JOIN_BIT |
                    (uint32_t)(range->join_first + index),
                item_min_x, item_min_y, item_max_x, item_max_y)) {
            abandon_grid(cache, range, cells, cell_count);
            free(refs);
            return true;
        }
    }
    size_t new_grid_bytes;
    if (!add_size(cache->grid_bytes, allocation_bytes, &new_grid_bytes)) {
        abandon_grid(cache, range, cells, cell_count);
        free(refs);
        return true;
    }
    range->grid_refs = refs;
    cache->grid_ref_count += reference_count;
    cache->grid_bytes = new_grid_bytes;
    return true;
}

bool raster_shape_stroke_grid_build(const svg_shape_document *doc,
                                    raster_shape_dash_cache *cache,
                                    svg_shape_diagnostic *diagnostic)
{
    if (cache == NULL || doc == NULL || cache->shapes == NULL) return true;
    for (size_t shape = 0U; shape < cache->shape_count; ++shape) {
        const svg_shape_stroke *stroke = &doc->strokes[shape];
        if (stroke->rgba[3] == 0U || stroke->width <= 0.0) continue;
        if (!build_shape_grid(cache, shape, stroke, diagnostic)) return false;
    }
    return true;
}

const raster_stroke_grid_cell *raster_shape_stroke_grid_lookup(
    const raster_dash_shape_range *range, double x, double y)
{
    if (range == NULL || range->grid_cells == NULL ||
        range->grid_columns == 0U || range->grid_rows == 0U) return NULL;
    uint16_t column, row;
    if (!grid_axis_cell(x, range->grid_min_x, range->grid_cell_size,
                        range->grid_columns, &column) ||
        !grid_axis_cell(y, range->grid_min_y, range->grid_cell_size,
                        range->grid_rows, &row)) return NULL;
    return &range->grid_cells[(size_t)row * range->grid_columns + column];
}

