            transform: affine_identity(), transform_node: None,
        });
        shape.filled = false;
        shape.stroke.rgba = [255; 4];
        shape.stroke.width = 0.25;
        shape.stroke.join = Linejoin::Round;
        let edge = Edge { a: Point { x: 0.25, y: 0.25 }, b: Point { x: 0.5, y: 0.5 } };
