                edges: vec![edge; count], subpaths: vec![], segments: vec![], numbers: vec![],
            }, edge_colors: vec![[255; 4]; count],
        }, &mut Run).unwrap();
    }
    builder.commit_draft(&draft, &mut Run).unwrap();
    (builder.freeze().unwrap(), source)
}
