fn exact_count() -> usize {
    let fixed = 176_371 * (size_of::<DashSegment>() + size_of::<DashJoin>())
        + 2 * size_of::<JobDashRange>() + 2 * size_of::<GridCell>();
    assert_eq!((CAP - fixed) % 8, 0);
